// ============================================================
// Pathways Build Generator
// Enforces Constitution Rule B4/H1 (Content-hashed generated files)
// ============================================================

import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { validateLedger } from './validate-ledger.mjs';

const ROOT_DIR = process.cwd();
const LEDGER_DIR = path.join(ROOT_DIR, 'docs', 'pathways', 'ledger');
const OUT_DIR = path.join(ROOT_DIR, 'src', 'pathways', 'facts');

if (!fs.existsSync(OUT_DIR)) {
  fs.mkdirSync(OUT_DIR, { recursive: true });
}

export function buildFacts() {
  console.log('1. Validating ledger rows before compilation...');
  const validation = validateLedger();
  if (!validation.ok) {
    console.error(`Cannot build: Ledger contains ${validation.errors.length} validation errors:`);
    validation.errors.forEach((e) => console.error(` - ${e}`));
    process.exit(1);
  }

  console.log(`2. Compiling ${validation.rowCount} ledger rows into strongly-typed generated facts...`);

  const ledgerFiles = fs.existsSync(LEDGER_DIR)
    ? fs.readdirSync(LEDGER_DIR).filter((f) => f.endsWith('.json'))
    : [];

  const allRows = [];
  for (const f of ledgerFiles) {
    const rows = JSON.parse(fs.readFileSync(path.join(LEDGER_DIR, f), 'utf8'));
    allRows.push(...rows);
  }

  // Separate program rows vs rule rows
  const programMap = new Map();
  const ruleRows = [];

  for (const row of allRows) {
    if (row.publisherType === 'government') {
      ruleRows.push(row);
    } else {
      let prog = programMap.get(row.subjectId);
      if (!prog) {
        prog = {
          id: row.subjectId,
          facts: {
            officialName: '',
            programName: '',
            programPageUrl: '',
            eligibility: {},
            stages: [],
          },
          evidence: {},
          lastChecked: row.retrievedAt ? row.retrievedAt.slice(0, 10) : new Date().toISOString().slice(0, 10),
        };
        programMap.set(row.subjectId, prog);
      }

      prog.evidence[row.field] = row;

      // Map closed field to facts structure
      if (row.field === 'officialName') prog.facts.officialName = row.value;
      else if (row.field === 'programName') prog.facts.programName = row.value;
      else if (row.field === 'programPageUrl') prog.facts.programPageUrl = row.value;
      else if (row.field === 'bondMonths') prog.facts.bondMonths = Number(row.value);
      else if (row.field === 'bondAmount') prog.facts.bondAmount = Number(row.value);
      else if (row.field === 'stipend') prog.facts.stipend = Number(row.value);
      else if (row.field.startsWith('eligibility.')) {
        const sub = row.field.replace('eligibility.', '');
        prog.facts.eligibility[sub] = row.value;
      } else if (row.field === 'stage.name') {
        prog.facts.stages.push({ name: String(row.value) });
      } else if (row.field === 'stage.type') {
        const lastStage = prog.facts.stages[prog.facts.stages.length - 1];
        if (lastStage) lastStage.type = row.value;
      }
    }
  }

  const programs = Array.from(programMap.values());

  // 1. Write programs.generated.ts
  writeHashedFile('programs.generated.ts', `import type { ProgramRecord } from '../schema/types';\n\nexport const PATHWAYS_PROGRAMS: ProgramRecord[] = ${JSON.stringify(programs, null, 2)};\n`);

  // 2. Write rules.generated.ts
  writeHashedFile('rules.generated.ts', `import type { RuleRow } from '../schema/types';\n\nexport const PATHWAYS_STATUTORY_RULES: RuleRow[] = ${JSON.stringify(ruleRows, null, 2)};\n`);

  // 3. Write manifest.generated.ts
  const manifest = {
    generatedAt: new Date().toISOString(),
    totalPrograms: programs.length,
    totalStatutoryRules: ruleRows.length,
    totalLedgerRows: allRows.length,
    programsHash: hashContent(JSON.stringify(programs)),
    rulesHash: hashContent(JSON.stringify(ruleRows)),
  };
  writeHashedFile('manifest.generated.ts', `export const PATHWAYS_MANIFEST = ${JSON.stringify(manifest, null, 2)};\n`);

  console.log(`✅ Compilation successful! Generated files written to src/pathways/facts/`);
}

function hashContent(content) {
  return crypto.createHash('sha256').update(content.trim()).digest('hex');
}

function writeHashedFile(fileName, contentBody) {
  const bodyHash = hashContent(contentBody);
  const fullContent = `// ============================================================\n// AUTO-GENERATED BY npm run pathways:build\n// DO NOT HAND-EDIT THIS FILE. YOUR CHANGES WILL BE OVERWRITTEN.\n// CONTENT-HASH: sha256:${bodyHash}\n// ============================================================\n\n${contentBody}`;
  fs.writeFileSync(path.join(OUT_DIR, fileName), fullContent, 'utf8');
}

if (process.argv[1]?.endsWith('build.mjs')) {
  buildFacts();
}
